<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Maintenance due report | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/staff">Triple R Gensan</a><nav class="staff-actions"><a href="/maintenance">Maintenance</a><a href="/fleet/vehicles">Fleet</a></nav></header><main class="page-shell"><section class="page-heading"><div><p class="eyebrow">Pull-only maintenance report</p><h1>Due and due soon</h1><p>Global defaults: <?= (int)$defaults['days'] ?> Manila calendar days or <?= (int)$defaults['kilometers'] ?> km. A schedule override replaces only its matching default.</p></div><a class="button-link" href="/maintenance/due?format=csv">Download CSV</a></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Plate</th><th>Vehicle</th><th>Schedule</th><th>State</th><th>Next date</th><th>Next mileage</th><th>Current mileage</th><th>Effective warning</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= $e($r['plate_number']) ?></td><td><?= $e($r['make'].' '.$r['model']) ?></td><td><?= $e($r['schedule_name']) ?></td><td><?= $e($r['due_state']) ?></td><td><?= $e($r['next_due_date']??'—') ?></td><td><?= $e($r['next_due_mileage']??'—') ?></td><td><?= $e($r['current_mileage']) ?></td><td><?= (int)$r['effective_due_soon_days'] ?> days / <?= (int)$r['effective_due_soon_mileage'] ?> km</td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8">No schedules are due or within their warning windows.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
